-- APEX RIDE: 036_motorcycle_model_directory.sql
-- Fonte: lista enviada pelo usuario em 24/10/2026; 1097 modelos de 50 marcas.
-- ATENCAO: a lista NAO contem anos-modelo nem fichas tecnicas, nem comprova producao atual.
-- Referencias sao de um indice independente; nao sao manuais oficiais de montadora.
-- Esta migracao nao modifica motorcycles, motorcycle_catalog_* nem revisoes/atividades pessoais.
CREATE TABLE IF NOT EXISTS motorcycle_model_directory (
  id uuid PRIMARY KEY,
  brand varchar(60) NOT NULL,
  model varchar(100) NOT NULL,
  reference_url text NOT NULL CHECK (reference_url ~ E'^https://[^[:space:]]+$'),
  reference_kind text NOT NULL DEFAULT 'third_party_index' CHECK (reference_kind IN ('third_party_index','manufacturer_official')),
  current_production_status text NOT NULL DEFAULT 'unknown' CHECK (current_production_status IN ('unknown','confirmed_current','discontinued')),
  first_model_year integer CHECK (first_model_year BETWEEN 1885 AND 2200),
  last_model_year integer CHECK (last_model_year BETWEEN 1885 AND 2200),
  imported_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (brand, model),
  CHECK (first_model_year IS NULL OR last_model_year IS NULL OR first_model_year <= last_model_year)
);
CREATE INDEX IF NOT EXISTS motorcycle_directory_search_idx ON motorcycle_model_directory
  USING gin(to_tsvector('simple', garage_normalize(brand || ' ' || model)));

ON CONFLICT (brand, model) DO NOTHING;

-- Vista de consulta: especificacoes so aparecem quando ja existe revisao reviewed da versao brasileira.
-- latest_reference_year NAO e automaticamente o ano da moto do usuario.
CREATE OR REPLACE VIEW motorcycle_model_directory_latest_reference AS
SELECT d.id, d.brand, d.model, d.reference_url, d.reference_kind,
       d.current_production_status, d.first_model_year, d.last_model_year,
       latest.variant_id AS latest_catalog_variant_id,
       latest.model_year AS latest_reference_year,
       latest.version_name AS latest_reference_version,
       latest.revision AS latest_reference_revision
FROM motorcycle_model_directory d
LEFT JOIN LATERAL (
  SELECT v.id AS variant_id, v.model_year, v.name AS version_name, r.revision
  FROM motorcycle_catalog_variants v
  JOIN motorcycle_catalog_models m ON m.id = v.model_id
  JOIN motorcycle_catalog_brands b ON b.id = m.brand_id
  JOIN motorcycle_catalog_revisions r ON r.variant_id = v.id AND r.status = 'reviewed'
  WHERE garage_normalize(b.name) = garage_normalize(d.brand)
    AND garage_normalize(m.name) = garage_normalize(d.model)
  ORDER BY v.model_year DESC, r.revision DESC, v.id
  LIMIT 1
) latest ON TRUE;

